//! The JFlex scanner behind [`StandardTokenizer`](super::StandardTokenizer).
//!
//! Equivalent to `org.apache.lucene.analysis.standard.StandardTokenizerImpl`
//! (Lucene 10.5.0, generated by JFlex 1.8.2 from
//! `StandardTokenizerImpl.jflex`). The DFA tables are the Java tables,
//! unpacked by `tools/gen/standard_tokenizer_tables.py` into
//! `standard_tokenizer_impl_tables.rs`; the scanner methods are ported line by
//! line from the generated Java class.
//!
//! # The reader is read as UTF-16
//!
//! The JFlex buffer is a `char[]` of UTF-16 code units, filled by
//! `java.io.Reader.read(char[], int, int)`; Rucene's
//! [`CharReader`] yields Unicode scalar values. The scanner therefore reads its
//! reader through a UTF-16 view ([`StandardTokenizerImpl::read_units`] and
//! [`StandardTokenizerImpl::read_unit`]): a request for `n` code units reads
//! at most `ceil(n / 2)` characters at a time, so it never consumes more than
//! a Java reader would, and when only one unit of room is left for a
//! supplementary character the view delivers its high surrogate and keeps the
//! low one for the next read, as a Java reader leaves it in the stream. The
//! buffer then holds exactly the code units Java's holds, and `zzRefill`'s
//! surrogate handling runs unchanged. Positions (`yychar`, `yylength`, the
//! offsets) count UTF-16 code units, as Java's do.

#![deny(unsafe_code)]

use super::standard_tokenizer_impl_tables::{
    ZZ_ACTION, ZZ_ATTRIBUTE, ZZ_CMAP_BLOCKS, ZZ_CMAP_TOP, ZZ_ROWMAP, ZZ_TRANS,
};
use super::{ALPHANUM, EMOJI, HANGUL, HIRAGANA, IDEOGRAPHIC, KATAKANA, NUM, SOUTHEAST_ASIAN};
use crate::analysis::{CharReader, CharTermAttribute};
use crate::error::{LuceneError, LuceneErrorKind, Result};

/// This character denotes the end of file.
///
/// Equivalent to `StandardTokenizerImpl.YYEOF`.
pub const YYEOF: i32 = -1;

/// Lexical States.
///
/// Equivalent to `StandardTokenizerImpl.YYINITIAL`.
pub const YYINITIAL: i32 = 0;

/// `ZZ_LEXSTATE[l]` is the state in the DFA for the lexical state `l`;
/// `ZZ_LEXSTATE[l+1]` is the state in the DFA for the lexical state `l` at the
/// beginning of a line.
const ZZ_LEXSTATE: [i32; 2] = [0, 0];

/// Error code for "Unknown internal scanner error".
const ZZ_UNKNOWN_ERROR: usize = 0;
/// Error code for "could not match input".
const ZZ_NO_MATCH: usize = 1;
/// Error code for "pushback value was too large".
const ZZ_PUSHBACK_2BIG: usize = 2;

/// Error messages for [`ZZ_UNKNOWN_ERROR`], [`ZZ_NO_MATCH`], and
/// [`ZZ_PUSHBACK_2BIG`] respectively.
const ZZ_ERROR_MSG: [&str; 3] = [
    "Unknown internal scanner error",
    "Error: could not match input",
    "Error: pushback value was too large",
];

/// Alphanumeric sequences.
pub const WORD_TYPE: i32 = ALPHANUM as i32;

/// Numbers.
pub const NUMERIC_TYPE: i32 = NUM as i32;

/// Chars in class `\p{Line_Break = Complex_Context}` are from South East Asian
/// scripts (Thai, Lao, Myanmar, Khmer, etc.). Sequences of these are kept
/// together as as a single token rather than broken up, because the logic
/// required to break them at word boundaries is too complex for UAX#29.
///
/// See Unicode Line Breaking Algorithm: <http://www.unicode.org/reports/tr14/#SA>
pub const SOUTH_EAST_ASIAN_TYPE: i32 = SOUTHEAST_ASIAN as i32;

/// Ideographic token type.
pub const IDEOGRAPHIC_TYPE: i32 = IDEOGRAPHIC as i32;

/// Hiragana token type.
pub const HIRAGANA_TYPE: i32 = HIRAGANA as i32;

/// Katakana token type.
pub const KATAKANA_TYPE: i32 = KATAKANA as i32;

/// Hangul token type.
pub const HANGUL_TYPE: i32 = HANGUL as i32;

/// Emoji token type.
pub const EMOJI_TYPE: i32 = EMOJI as i32;

/// This class implements Word Break rules from the Unicode Text Segmentation
/// algorithm, as specified in
/// [Unicode Standard Annex #29](http://unicode.org/reports/tr29/).
///
/// Tokens produced are of the following types:
///
/// * `<ALPHANUM>`: A sequence of alphabetic and numeric characters
/// * `<NUM>`: A number
/// * `<SOUTHEAST_ASIAN>`: A sequence of characters from South and Southeast
///   Asian languages, including Thai, Lao, Myanmar, and Khmer
/// * `<IDEOGRAPHIC>`: A single CJKV ideographic character
/// * `<HIRAGANA>`: A single hiragana character
/// * `<KATAKANA>`: A sequence of katakana characters
/// * `<HANGUL>`: A sequence of Hangul characters
/// * `<EMOJI>`: A sequence of Emoji characters
///
/// Equivalent to `org.apache.lucene.analysis.standard.StandardTokenizerImpl`.
/// Java's scanner holds its `java.io.Reader`; a [`CharReader`] is owned by the
/// [`Tokenizer`](crate::analysis::Tokenizer), so the methods that read take it
/// as a parameter.
#[derive(Debug)]
pub struct StandardTokenizerImpl {
    /// Initial size of the lookahead buffer (`ZZ_BUFFERSIZE`).
    zz_buffer_size: usize,
    /// Current state of the DFA.
    zz_state: i32,
    /// Current lexical state.
    zz_lexical_state: i32,
    /// This buffer contains the current text to be matched and is the source
    /// of the [`yytext`](Self::yytext) string.
    zz_buffer: Vec<u16>,
    /// Text position at the last accepting state.
    zz_marked_pos: usize,
    /// Current text position in the buffer.
    zz_current_pos: usize,
    /// Marks the beginning of the [`yytext`](Self::yytext) string in the
    /// buffer.
    zz_start_read: usize,
    /// Marks the last character in the buffer, that has been read from input.
    zz_end_read: usize,
    /// Whether the scanner is at the end of file.
    zz_at_eof: bool,
    /// The number of occupied positions in `zz_buffer` beyond `zz_end_read`.
    ///
    /// When a lead/high surrogate has been read from the input stream into
    /// the final `zz_buffer` position, this will have a value of 1;
    /// otherwise, it will have a value of 0.
    zz_final_high_surrogate: usize,
    /// Number of newlines encountered up to the start of the matched text.
    #[allow(dead_code)] // `@SuppressWarnings("unused")`, as in Java
    yyline: i32,
    /// Number of characters from the last newline up to the start of the
    /// matched text.
    #[allow(dead_code)] // `@SuppressWarnings("unused")`, as in Java
    yycolumn: i32,
    /// Number of characters up to the start of the matched text.
    yychar: i64,
    /// Whether the scanner is currently at the beginning of a line.
    #[allow(dead_code)] // `@SuppressWarnings("unused")`, as in Java
    zz_at_bol: bool,
    /// Whether the user-EOF-code has already been executed.
    #[allow(dead_code)] // `@SuppressWarnings("unused")`, as in Java
    zz_eof_done: bool,
    /// The current token decoded to `char`s for [`get_text`](Self::get_text),
    /// kept across tokens. Java has no such buffer: its term holds the UTF-16
    /// code units `zzBuffer` holds.
    text_scratch: Vec<char>,
}

impl Default for StandardTokenizerImpl {
    fn default() -> Self {
        Self::new()
    }
}

impl StandardTokenizerImpl {
    /// Creates a new scanner.
    ///
    /// Equivalent to `StandardTokenizerImpl(java.io.Reader in)`; the reader is
    /// passed to each reading method instead.
    pub fn new() -> Self {
        // `private int ZZ_BUFFERSIZE = 255;` and
        // `private char zzBuffer[] = new char[ZZ_BUFFERSIZE];`
        let zz_buffer_size = 255;
        Self {
            zz_buffer_size,
            zz_state: 0,
            zz_lexical_state: YYINITIAL,
            zz_buffer: vec![0; zz_buffer_size],
            zz_marked_pos: 0,
            zz_current_pos: 0,
            zz_start_read: 0,
            zz_end_read: 0,
            zz_at_eof: false,
            zz_final_high_surrogate: 0,
            yyline: 0,
            yycolumn: 0,
            yychar: 0,
            zz_at_bol: true,
            zz_eof_done: false,
            text_scratch: Vec::new(),
        }
    }

    /// Character count processed so far.
    ///
    /// Equivalent to `StandardTokenizerImpl.yychar()`: UTF-16 code units,
    /// truncated to `int` ("jflex supports > 2GB docs but not lucene").
    pub fn yychar(&self) -> i32 {
        self.yychar as i32
    }

    /// Fills `t` with the current token text.
    ///
    /// Equivalent to `StandardTokenizerImpl.getText(CharTermAttribute)`,
    /// `t.copyBuffer(zzBuffer, zzStartRead, zzMarkedPos-zzStartRead)`. The
    /// attribute holds characters, so the token's UTF-16 code units are
    /// decoded first; a token is a sequence of whole code points of the
    /// buffer, so it holds no unpaired surrogate.
    pub fn get_text(&mut self, t: &mut dyn CharTermAttribute) {
        // Java copies `zzBuffer` straight into the term
        // (`StandardTokenizerImpl.java:723-725`: `t.copyBuffer(zzBuffer,
        // zzStartRead, zzMarkedPos-zzStartRead)`). The port's term holds
        // `char`s, so the code units are decoded first, into a buffer kept
        // across tokens rather than one allocated per token.
        let units = &self.zz_buffer[self.zz_start_read..self.zz_marked_pos];
        self.text_scratch.clear();
        self.text_scratch.extend(
            char::decode_utf16(units.iter().copied())
                .map(|r| r.unwrap_or(char::REPLACEMENT_CHARACTER)),
        );
        t.copy_buffer(&self.text_scratch, 0, self.text_scratch.len());
    }

    /// Sets the scanner buffer size in chars.
    ///
    /// Equivalent to `StandardTokenizerImpl.setBufferSize(int)`: a new buffer
    /// of `num_chars` code units receives as much of the old one as fits.
    pub fn set_buffer_size(&mut self, num_chars: usize) {
        self.zz_buffer_size = num_chars;
        let mut new_zz_buffer = vec![0u16; self.zz_buffer_size];
        let n = self.zz_buffer.len().min(self.zz_buffer_size);
        new_zz_buffer[..n].copy_from_slice(&self.zz_buffer[..n]);
        self.zz_buffer = new_zz_buffer;
    }

    /// Translates raw input code points to DFA table row.
    ///
    /// Equivalent to `StandardTokenizerImpl.zzCMap(int)`.
    fn zz_cmap(input: i32) -> i32 {
        let offset = input & 255;
        if offset == input {
            ZZ_CMAP_BLOCKS[offset as usize]
        } else {
            ZZ_CMAP_BLOCKS[(ZZ_CMAP_TOP[(input >> 8) as usize] | offset) as usize]
        }
    }

    /// Refills the input buffer.
    ///
    /// Equivalent to `StandardTokenizerImpl.zzRefill()`: returns `false` iff
    /// there was new input.
    ///
    /// # Errors
    ///
    /// What the reader raises, and the `ArrayIndexOutOfBoundsException` or
    /// `IndexOutOfBoundsException` Java raises once a
    /// [`set_buffer_size`](Self::set_buffer_size) in the middle of a stream
    /// left the buffer shorter than the text it holds.
    fn zz_refill(&mut self, reader: &mut dyn CharReader) -> Result<bool> {
        /* first: make room (if you can) */
        if self.zz_start_read > 0 {
            self.zz_end_read += self.zz_final_high_surrogate;
            self.zz_final_high_surrogate = 0;
            array_copy_within(
                &mut self.zz_buffer,
                self.zz_start_read,
                0,
                self.zz_end_read as i64 - self.zz_start_read as i64,
            )?;

            /* translate stored positions */
            self.zz_end_read -= self.zz_start_read;
            self.zz_current_pos -= self.zz_start_read;
            self.zz_marked_pos -= self.zz_start_read;
            self.zz_start_read = 0;
        }

        /* fill the buffer with new input */
        let requested = self.zz_buffer.len() as i64
            - self.zz_end_read as i64
            - self.zz_final_high_surrogate as i64;
        if requested == 0 {
            return Ok(true);
        }
        let num_read = self.read_units(reader, self.zz_end_read, requested)?;

        /* not supposed to occur according to specification of java.io.Reader */
        if num_read == 0 {
            return Err(LuceneError::from(LuceneErrorKind::Io(std::io::Error::other(
                "Reader returned 0 characters. See JFlex examples/zero-reader for a workaround.",
            ))));
        }
        if num_read > 0 {
            self.zz_end_read += num_read as usize;
            if is_high_surrogate(self.zz_buffer[self.zz_end_read - 1]) {
                if num_read == requested {
                    // We requested too few chars to encode a full Unicode character
                    self.zz_end_read -= 1;
                    self.zz_final_high_surrogate = 1;
                    if num_read == 1 {
                        return Ok(true);
                    }
                } else {
                    // There is room in the buffer for at least one more char
                    let c = self.read_unit(reader)?; // Expecting to read a paired low surrogate char
                    if c == -1 {
                        return Ok(true);
                    } else {
                        self.zz_buffer[self.zz_end_read] = c as u16;
                        self.zz_end_read += 1;
                    }
                }
            }
            /* potentially more input available */
            return Ok(false);
        }

        /* numRead < 0 ==> end of stream */
        Ok(true)
    }

    /// `zzReader.read(zzBuffer, off, len)`: the number of code units stored
    /// at `off`, or `-1` at the end of the stream.
    ///
    /// # Errors
    ///
    /// What the reader raises, and, for a negative `len` (a buffer shrunk
    /// under its text), the `IndexOutOfBoundsException` of
    /// `java.io.StringReader.read` (`Range [off, off + len) out of bounds for
    /// length n`).
    fn read_units(&mut self, reader: &mut dyn CharReader, off: usize, len: i64) -> Result<i64> {
        if len < 0 {
            return Err(LuceneError::from(LuceneErrorKind::Unchecked {
                class: "java.lang.IndexOutOfBoundsException",
                message: Some(format!(
                    "Range [{off}, {off} + {len}) out of bounds for length {}",
                    self.zz_buffer.len()
                )),
                cause: None,
            }));
        }
        let len = len as usize;
        if len == 0 {
            // `Reader.read` answers 0 for an empty request.
            return Ok(0);
        }
        let got = reader.read(&mut self.zz_buffer[off..off + len])?;
        Ok(if got == 0 { -1 } else { got as i64 })
    }

    /// `zzReader.read()`: the next code unit, or `-1` at the end of the
    /// stream.
    ///
    /// # Errors
    ///
    /// What the reader raises.
    fn read_unit(&mut self, reader: &mut dyn CharReader) -> Result<i32> {
        let mut one = [0u16; 1];
        if reader.read(&mut one)? == 0 {
            return Ok(-1);
        }
        Ok(i32::from(one[0]))
    }

    /// Closes the input reader.
    ///
    /// Equivalent to `StandardTokenizerImpl.yyclose()`.
    ///
    /// # Errors
    ///
    /// What closing the reader raises.
    pub fn yyclose(&mut self, reader: &mut dyn CharReader) -> Result<()> {
        self.zz_at_eof = true; // indicate end of file
        self.zz_end_read = self.zz_start_read; // invalidate buffer
        reader.close()
    }

    /// Resets the scanner to read from a new input stream.
    ///
    /// Does not close the old reader.
    ///
    /// All internal variables are reset, the old input stream **cannot** be
    /// reused (internal buffer is discarded and lost). Lexical state is set to
    /// `ZZ_INITIAL`.
    ///
    /// Internal scan buffer is resized down to its initial length, if it has
    /// grown.
    ///
    /// Equivalent to `StandardTokenizerImpl.yyreset(java.io.Reader)`; the new
    /// reader is the one passed to the next reading call.
    pub fn yyreset(&mut self) {
        self.zz_eof_done = false;
        self.yy_reset_position();
        self.zz_lexical_state = YYINITIAL;
        if self.zz_buffer.len() > self.zz_buffer_size {
            self.zz_buffer = vec![0; self.zz_buffer_size];
        }
    }

    /// Resets the input position.
    ///
    /// Equivalent to `StandardTokenizerImpl.yyResetPosition()`.
    fn yy_reset_position(&mut self) {
        self.zz_at_bol = true;
        self.zz_at_eof = false;
        self.zz_current_pos = 0;
        self.zz_marked_pos = 0;
        self.zz_start_read = 0;
        self.zz_end_read = 0;
        self.zz_final_high_surrogate = 0;
        self.yyline = 0;
        self.yycolumn = 0;
        self.yychar = 0;
    }

    /// Returns whether the scanner has reached the end of the reader it reads
    /// from.
    ///
    /// Equivalent to `StandardTokenizerImpl.yyatEOF()`.
    pub fn yyat_eof(&self) -> bool {
        self.zz_at_eof
    }

    /// Returns the current lexical state.
    ///
    /// Equivalent to `StandardTokenizerImpl.yystate()`.
    pub fn yystate(&self) -> i32 {
        self.zz_lexical_state
    }

    /// Enters a new lexical state.
    ///
    /// Equivalent to `StandardTokenizerImpl.yybegin(int)`.
    pub fn yybegin(&mut self, new_state: i32) {
        self.zz_lexical_state = new_state;
    }

    /// Returns the text matched by the current regular expression.
    ///
    /// Equivalent to `StandardTokenizerImpl.yytext()`.
    pub fn yytext(&self) -> String {
        String::from_utf16_lossy(&self.zz_buffer[self.zz_start_read..self.zz_marked_pos])
    }

    /// Returns the UTF-16 code unit at the given position from the matched
    /// text, a value from 0 to `yylength()-1`.
    ///
    /// Equivalent to `StandardTokenizerImpl.yycharat(int)`.
    pub fn yycharat(&self, position: usize) -> u16 {
        self.zz_buffer[self.zz_start_read + position]
    }

    /// How many characters (UTF-16 code units) were matched.
    ///
    /// Equivalent to `StandardTokenizerImpl.yylength()`.
    pub fn yylength(&self) -> i32 {
        (self.zz_marked_pos - self.zz_start_read) as i32
    }

    /// Reports an error that occurred while scanning.
    ///
    /// In a well-formed scanner (no or only correct usage of
    /// `yypushback(int)` and a match-all fallback rule) this method will only
    /// be called with things that "Can't Possibly Happen".
    ///
    /// Equivalent to `StandardTokenizerImpl.zzScanError(int)`, which throws a
    /// `java.lang.Error`.
    ///
    /// # Panics
    ///
    /// Always, with the message of `error_code`, as Java throws an `Error`.
    fn zz_scan_error(error_code: usize) -> ! {
        let message = ZZ_ERROR_MSG
            .get(error_code)
            .copied()
            .unwrap_or(ZZ_ERROR_MSG[ZZ_UNKNOWN_ERROR]);
        panic!("{message}");
    }

    /// Pushes the specified amount of characters back into the input stream.
    ///
    /// They will be read again by then next call of the scanning method.
    ///
    /// Equivalent to `StandardTokenizerImpl.yypushback(int)`.
    ///
    /// # Panics
    ///
    /// When `number` is greater than [`yylength`](Self::yylength), as Java's
    /// `zzScanError(ZZ_PUSHBACK_2BIG)` throws an `Error`.
    pub fn yypushback(&mut self, number: i32) {
        if number > self.yylength() {
            Self::zz_scan_error(ZZ_PUSHBACK_2BIG);
        }
        self.zz_marked_pos = (self.zz_marked_pos as i64 - i64::from(number)) as usize;
    }

    /// Resumes scanning until the next regular expression is matched, the end
    /// of input is encountered or an I/O-Error occurs.
    ///
    /// Equivalent to `StandardTokenizerImpl.getNextToken()`: returns the token
    /// type, or [`YYEOF`].
    ///
    /// # Errors
    ///
    /// What `reader` raises, and the `IndexOutOfBoundsException` of
    /// `Character.codePointAt` once a
    /// [`set_buffer_size`](Self::set_buffer_size) in the middle of a stream
    /// left the buffer shorter than the text it holds.
    ///
    /// # Panics
    ///
    /// When no rule matches, as Java's `zzScanError(ZZ_NO_MATCH)` throws an
    /// `Error`; the grammar's catch-all rule makes this unreachable.
    pub fn get_next_token(&mut self, reader: &mut dyn CharReader) -> Result<i32> {
        let mut zz_input: i32;
        let mut zz_action: i32;

        // cached fields:
        let mut zz_current_pos_l: usize;
        let mut zz_marked_pos_l: usize;
        let mut zz_end_read_l = self.zz_end_read;

        loop {
            zz_marked_pos_l = self.zz_marked_pos;

            self.yychar += zz_marked_pos_l as i64 - self.zz_start_read as i64;

            zz_action = -1;

            zz_current_pos_l = zz_marked_pos_l;
            self.zz_current_pos = zz_marked_pos_l;
            self.zz_start_read = zz_marked_pos_l;

            self.zz_state = ZZ_LEXSTATE[self.zz_lexical_state as usize];

            // set up zzAction for empty match case:
            let mut zz_attributes = ZZ_ATTRIBUTE[self.zz_state as usize];
            if (zz_attributes & 1) == 1 {
                zz_action = self.zz_state;
            }

            // zzForAction:
            loop {
                if zz_current_pos_l < zz_end_read_l {
                    zz_input = code_point_at(&self.zz_buffer, zz_current_pos_l, zz_end_read_l)?;
                    zz_current_pos_l += char_count(zz_input);
                } else if self.zz_at_eof {
                    zz_input = YYEOF;
                    break;
                } else {
                    // store back cached positions
                    self.zz_current_pos = zz_current_pos_l;
                    self.zz_marked_pos = zz_marked_pos_l;
                    let eof = self.zz_refill(reader)?;
                    // get translated positions and possibly new buffer
                    zz_current_pos_l = self.zz_current_pos;
                    zz_marked_pos_l = self.zz_marked_pos;
                    zz_end_read_l = self.zz_end_read;
                    if eof {
                        zz_input = YYEOF;
                        break;
                    } else {
                        zz_input = code_point_at(&self.zz_buffer, zz_current_pos_l, zz_end_read_l)?;
                        zz_current_pos_l += char_count(zz_input);
                    }
                }
                let zz_next = ZZ_TRANS
                    [(ZZ_ROWMAP[self.zz_state as usize] + Self::zz_cmap(zz_input)) as usize];
                if zz_next == -1 {
                    break;
                }
                self.zz_state = zz_next;

                zz_attributes = ZZ_ATTRIBUTE[self.zz_state as usize];
                if (zz_attributes & 1) == 1 {
                    zz_action = self.zz_state;
                    zz_marked_pos_l = zz_current_pos_l;
                    if (zz_attributes & 8) == 8 {
                        break;
                    }
                }
            }

            // store back cached position
            self.zz_marked_pos = zz_marked_pos_l;

            if zz_input == YYEOF && self.zz_start_read == self.zz_current_pos {
                self.zz_at_eof = true;
                return Ok(YYEOF);
            } else {
                match if zz_action < 0 {
                    zz_action
                } else {
                    ZZ_ACTION[zz_action as usize]
                } {
                    1 => {
                        /* Break so we don't hit fall-through warning: */
                        /* Not numeric, word, ideographic, hiragana, emoji or SE Asian -- ignore it. */
                    }
                    2 => return Ok(NUMERIC_TYPE),
                    3 => return Ok(WORD_TYPE),
                    4 => return Ok(EMOJI_TYPE),
                    5 => return Ok(SOUTH_EAST_ASIAN_TYPE),
                    6 => return Ok(HANGUL_TYPE),
                    7 => return Ok(IDEOGRAPHIC_TYPE),
                    8 => return Ok(KATAKANA_TYPE),
                    9 => return Ok(HIRAGANA_TYPE),
                    10..=18 => {}
                    _ => Self::zz_scan_error(ZZ_NO_MATCH),
                }
            }
        }
    }
}

/// `Character.isHighSurrogate(char)`.
fn is_high_surrogate(unit: u16) -> bool {
    (0xD800..=0xDBFF).contains(&unit)
}

/// `Character.isLowSurrogate(char)`.
fn is_low_surrogate(unit: u16) -> bool {
    (0xDC00..=0xDFFF).contains(&unit)
}

/// `Character.charCount(int)`.
fn char_count(code_point: i32) -> usize {
    if code_point >= 0x10000 {
        2
    } else {
        1
    }
}

/// `Character.codePointAt(char[] a, int index, int limit)`.
///
/// # Errors
///
/// Java's `IndexOutOfBoundsException` (no message) when `index >= limit` or
/// `limit > a.length`.
fn code_point_at(a: &[u16], index: usize, limit: usize) -> Result<i32> {
    if index >= limit || limit > a.len() {
        return Err(LuceneError::from(LuceneErrorKind::Unchecked {
            class: "java.lang.IndexOutOfBoundsException",
            message: None,
            cause: None,
        }));
    }
    let c1 = a[index];
    if is_high_surrogate(c1) && index + 1 < limit {
        let c2 = a[index + 1];
        if is_low_surrogate(c2) {
            return Ok(0x10000 + ((i32::from(c1) - 0xD800) << 10) + (i32::from(c2) - 0xDC00));
        }
    }
    Ok(i32::from(c1))
}

/// `System.arraycopy(buf, src_pos, buf, dest_pos, length)` on one `char[]`.
///
/// # Errors
///
/// Java's `ArrayIndexOutOfBoundsException`, with its message, for a negative
/// length or a range past the end of the array.
fn array_copy_within(buf: &mut [u16], src_pos: usize, dest_pos: usize, length: i64) -> Result<()> {
    let aioobe = |message: String| {
        LuceneError::from(LuceneErrorKind::Unchecked {
            class: "java.lang.ArrayIndexOutOfBoundsException",
            message: Some(message),
            cause: None,
        })
    };
    if length < 0 {
        return Err(aioobe(format!("arraycopy: length {length} is negative")));
    }
    let len = buf.len();
    if src_pos as i64 + length > len as i64 {
        return Err(aioobe(format!(
            "arraycopy: last source index {} out of bounds for char[{len}]",
            src_pos as i64 + length
        )));
    }
    if dest_pos as i64 + length > len as i64 {
        return Err(aioobe(format!(
            "arraycopy: last destination index {} out of bounds for char[{len}]",
            dest_pos as i64 + length
        )));
    }
    let length = length as usize;
    buf.copy_within(src_pos..src_pos + length, dest_pos);
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::analysis::StringCharReader;

    /// Every token of `text`: its type, `yychar`, `yylength` and `yytext`.
    fn scan(text: &str, buffer: usize) -> Vec<(i32, i32, i32, String)> {
        let mut scanner = StandardTokenizerImpl::new();
        scanner.set_buffer_size(buffer);
        scanner.yyreset();
        let mut reader = StringCharReader::new(text);
        let mut out = Vec::new();
        loop {
            let t = scanner.get_next_token(&mut reader).unwrap();
            if t == YYEOF {
                break;
            }
            out.push((t, scanner.yychar(), scanner.yylength(), scanner.yytext()));
        }
        out
    }

    #[test]
    fn the_scanner_counts_utf16_units_and_types_tokens() {
        assert_eq!(
            scan("ab \u{1F4A9}12", 255),
            vec![
                (WORD_TYPE, 0, 2, "ab".to_string()),
                (EMOJI_TYPE, 3, 2, "\u{1F4A9}".to_string()),
                (NUMERIC_TYPE, 5, 2, "12".to_string()),
            ]
        );
    }

    /// A one-unit buffer cannot hold a supplementary character: `zzRefill`
    /// holds back its high surrogate and reports the end of the input.
    #[test]
    fn a_one_unit_buffer_ends_the_stream_at_a_supplementary_character() {
        assert_eq!(
            scan("a\u{1F4A9}b", 1),
            vec![(WORD_TYPE, 0, 1, "a".to_string())]
        );
    }

    /// With room for one unit only, the UTF-16 view keeps the low surrogate
    /// for the next read, which delivers it first.
    #[test]
    fn the_utf16_view_holds_back_the_low_surrogate() {
        let mut scanner = StandardTokenizerImpl::new();
        let mut reader = StringCharReader::new("\u{1F4A9}x");
        assert_eq!(scanner.read_units(&mut reader, 0, 1).unwrap(), 1);
        assert_eq!(scanner.zz_buffer[0], 0xD83D);
        assert_eq!(scanner.read_units(&mut reader, 1, 2).unwrap(), 2);
        assert_eq!(&scanner.zz_buffer[1..3], &[0xDCA9, u16::from(b'x')]);
        assert_eq!(scanner.read_units(&mut reader, 3, 2).unwrap(), -1);
    }

    #[test]
    fn code_point_at_and_arraycopy_raise_javas_exceptions() {
        assert!(code_point_at(&[0x61], 1, 1).is_err());
        assert!(code_point_at(&[0x61], 0, 2).is_err());
        assert_eq!(code_point_at(&[0xD83D, 0xDCA9], 0, 1).unwrap(), 0xD83D);
        let mut buf = [1u16, 2, 3];
        assert_eq!(
            array_copy_within(&mut buf, 2, 0, 2).unwrap_err().to_string(),
            "java.lang.ArrayIndexOutOfBoundsException: arraycopy: last source index 4 out of bounds for char[3]"
        );
        array_copy_within(&mut buf, 1, 0, 2).unwrap();
        assert_eq!(buf, [2, 3, 3]);
    }

    #[test]
    #[should_panic(expected = "Error: pushback value was too large")]
    fn pushback_past_the_match_is_a_scan_error() {
        let mut scanner = StandardTokenizerImpl::new();
        scanner.yypushback(1);
    }
}
